n = int(input())
Sosu = []
for i in range(2, n + 1):
    warikireru = 0
    for j in range(2, i):
        if i % j == 0:
            warikireru = 1
    if warikireru == 0:
        Sosu.append(i)
kotae = ""
for i in range(0, len(Sosu)):
    if i > 0:
        kotae = kotae + " "
    kotae = kotae + str(Sosu[i])
print(kotae)

Data = [3, 18, 29, 33, 48, 52, 62, 77, 89, 97]

def sagasu(Data, atai):
    hidari = 0
    migi = len(Data) - 1
    while hidari <= migi:
        aida = (hidari + migi) // 2
        if Data[aida] == atai:
            return aida
        elif Data[aida] < atai:
            hidari = aida + 1
        else:
            migi = aida - 1
    return -1

atai = int(input())
print(sagasu(Data, atai))

